        }

        f[0] = 0;
        g[0] = 1;
        for (unsigned int i = 1; i <= m; i++) {
            unsigned_type val = fmod(fmod(c[i - 1] * f[i - 1] * g[m - i + 1], MOD) + fmod(c[i - 1] * g[i - 1] * f[m - i + 1], MOD) + (c[i - 1] * g[i - 1] * g[m - i + 1]) % MOD * (i + 2) % MOD, MOD);
            f[i] = val;
            val *= c[i - 1] * g[i - 1] * g[m - i + 1];
            g[i] = fmod(val % MOD + MOD, MOD);
        }

        ways[0][0] = 1;
        for (unsigned int j = 0; j <= std::min(n - 1, m); j++) {
            dp[0][j] = dp[j][0];
            unsigned_type D = 0;
            for (unsigned int k = 0; k <= j; k++) {
